local NewInstance = Instance.new

local cloneref = (function()
    local Native = cloneref
    if not Native then
        return function(Object)
            return Object
        end
    end

    local Cache = setmetatable({}, {__mode = "v"})

    return function(Object)
        if not Object then
            return nil
        end

        local ok, Id = pcall(function() return Object:GetDebugId() end)
        if not ok or not Id then
            local okClone, Cloned = pcall(Native, Object)
            return (okClone and Cloned) or Object
        end

        local Cached = Cache[Id]
        if Cached then
            return Cached
        end

        local okClone, Cloned = pcall(Native, Object)
        if okClone and Cloned then
            Cache[Id] = Cloned
            return Cloned
        end

        return Object
    end
end)()

local function GetService(Name)
    local ok, serv = pcall(function() return cloneref(game:GetService(Name)) end)
    return (ok and serv) or nil
end

