        function(e)
            for _, Obj in self:GetSelectionList() do
                pcall(function()
                    Obj:SetAttribute(e.Name, nil)
                end)
            end

            self:CloseModal()
            if self.SelectedInstance then
                self:RenderProperties(self.SelectedInstance)
            end
        end,
    true)
end

