    local rawRMD = [==[[{"Name":"BindableFunction","Summary":"Allow functions defined in one script to be called by another script","ExplorerOrder":4,"ExplorerImageIndex":66,"Browsable":true,"PreferredParent":"","Members":[{"Name":"Invoke","Summary":"Causes the function assigned to OnInvoke to be called. Arguments passed to this function get passed to OnInvoke function.","Browsable":true,"Deprecated":false,"Preliminary":false,"IsBackend":false},{"Name":"OnInvoke","Summary":"Should be defined as a function. This function is called when Invoke() is called. Number of arguments is variable.","Browsable":true,"Deprecated":false,"Preliminary":false,"IsBackend":false}],"Deprecated":false,"Preliminary":false,"IsBackend":false},{"Name":"BindableEvent","Summary":"Allow events defined in one script to be subscribed to by another script","ExplorerOrder":5,"ExplorerImageIndex":67,"Browsable":true,"PreferredParent":"","Members":[{"Name":"Fire","Summary":"Used to make the custom event fire (see Event for more info). Arguments can be variable length.","Browsable":true,"Deprecated":false,"Preliminary":false,"IsBackend":false},{"Name":"Event","Summary":"This event fires when the Fire() method is used.  Receives the variable length arguments from Fire().","Browsable":true,"Deprecated":false,"Preliminary":false,"IsBackend":false}],"Deprecated":false,"Preliminary":false,"IsBackend":false},{"Name":"TouchTransmitter","Summary":"Used by networking and replication code to transmit touch events - no other purpose","ExplorerOrder":3,"ExplorerImageIndex":37,"Browsable":"false","PreferredParent":"","Members":[],"Deprecated":false,"Preliminary":false,"IsBackend":false},{"Name":"ForceField","Summary":"Prevents joint breakage from explosions, and stops Humanoids from taking damage","ExplorerOrder":3,"ExplorerImageIndex":37,"Browsable":true,"PreferredParent":"","Members":[],"Deprecated":false,"Preliminary":false,"IsBackend":false},{"Name":"PluginManager","Summary":"","ExplorerOrder":0,"ExplorerImag