local DecodedRobloxAPI = nil
local DecodedReflectionMetadata = nil

function Explorer:GetRobloxAPI()
    if DecodedRobloxAPI then return DecodedRobloxAPI end
    if not RawRobloxAPI then return nil end
    local ok, res = pcall(function()
        return Services.HttpService:JSONDecode(RawRobloxAPI)
    end)
    if ok and res then
        DecodedRobloxAPI = res
        return res
    end
    return nil
end

function Explorer:GetReflectionMetadata()
    if DecodedReflectionMetadata then return DecodedReflectionMetadata end
    if not RawReflectionMetadata then return nil end
    local ok, res = pcall(function()
        return Services.HttpService:JSONDecode(RawReflectionMetadata)
    end)
    if ok and res then
        DecodedReflectionMetadata = res
        return res
    end
    return nil
end

