function Explorer:OpenNotebook()
    if self.NotebookWindow and self.NotebookWindow.Parent then
        self.NotebookWindow.Visible = not self.NotebookWindow.Visible
        return
    end

    local NotebookWin = VexUI:CreateWindow({
        Parent = self.ScreenGui;
        Title = "GokuDex Notebook";
        Size = UDim2.fromOffset(560, 420);
        Position = UDim2.fromOffset(100, 100);
    })

    self.NotebookWindow = NotebookWin.Frame

    NotebookWin:AddTitleButton("X", 26, true, function()
        self.NotebookWindow.Visible = false
    end, "CloseIcon")

    local WindowBody = NotebookWin.Body

    local TopBar = VexUI:CreateInstance("Frame", {
        Size = UDim2.new(1, -16, 0, 28);
        Position = UDim2.new(0, 8, 0, 6);
        BackgroundTransparency = 1;
        Parent = WindowBody;
    })
    local TopLayout = VexUI:AddListLayout(TopBar, 6, Enum.FillDirection.Horizontal)
    TopLayout.VerticalAlignment = Enum.VerticalAlignment.Center

    local function CreateButton(Text, Callback, Width)
        local Btn = VexUI:CreateInstance("TextButton", {
            Size = UDim2.new(0, Width or 65, 1, 0);
            BackgroundColor3 = Theme.Field;
            BorderSizePixel = 0;
            AutoButtonColor = false;
            Font = Fonts.SemiBold;
            Text = Text;
            TextColor3 = Theme.Text;
            TextSize = 11;
            Parent = TopBar;
        })
        VexUI:AddStroke(Btn, "Border", 1)
        Btn.MouseButton1Click:Connect(Callback)
        return Btn
    end

    local NoteScroll = VexUI:CreateInstance("ScrollingFrame", {
        Size = UDim2.new(1, -16, 1, -78);
        Position = UDim2.new(0, 8, 0, 38);
        BackgroundColor3 = Theme.Background;
        BorderSizePixel = 0;
        ScrollBarThickness = 4;
        CanvasSize = UDim2.new(0, 0, 0, 0);
        AutomaticCanvasSize = Enum.AutomaticSize.XY;
        Parent = WindowBody;
    })
    VexUI:AddStroke(NoteScroll, "Border", 1)
    VexUI:AddPadding(NoteScroll, 6, 8, 6, 8)

    local NoteBox = VexUI:CreateInstance("TextBox", {
        Size = UDim2.new(1, 0, 1, 0);
        AutomaticSize = Enum.AutomaticSize.XY;
        BackgroundTransparency = 1;
        ClearTextOnFocus = false;
        Font = Fonts.Mono;
        MultiLine = true;
        PlaceholderText = "-- GokuDex Scratchpad & Notes\n-- Write Lua code, dump remotes, or save notes here...\n";
        PlaceholderColor3 = Theme.TextFaded;
        Text = getgenv()._GokuDexNotes or "";
        TextColor3 = Theme.Text;
        TextSize = 12;
        TextXAlignment = Enum.TextXAlignment.Left;
        TextYAlignment = Enum.TextYAlignment.Top;
        Parent = NoteScroll;
    })

    local NotesPath = "gokudex_notes.txt"
    if readfile and isfile and isfile(NotesPath) then
        local ok, data = pcall(readfile, NotesPath)
        if ok and data and data ~= "" then
            NoteBox.Text = data
        end
    end

    local StatusLabel = VexUI:CreateInstance("TextLabel", {
        Size = UDim2.new(1, -16, 0, 24);
        Position = UDim2.new(0, 8, 1, -30);
        BackgroundTransparency = 1;
        Font = Fonts.Mono;
        Text = "Ready | Lines: 1 | Chars: 0";
        TextColor3 = Theme.TextDim;
        TextSize = 11;
        TextXAlignment = Enum.TextXAlignment.Left;
        Parent = WindowBody;
    })

    local function UpdateStats()
        local txt = NoteBox.Text
        local lines = select(2, txt:gsub("\n", "\n")) + 1
        StatusLabel.Text = string.format("Ready | Lines: %d | Chars: %d", lines, #txt)
        getgenv()._GokuDexNotes = txt
    end

    NoteBox:GetPropertyChangedSignal("Text"):Connect(UpdateStats)
    UpdateStats()

    CreateButton("Run Code", function()
        local code = NoteBox.Text
        if code and code ~= "" then
            local fn, err = loadstring(code)
            if fn then
                task.spawn(fn)
                self:ShowNotification("Notebook", "Script executed successfully!", "info")
            else
                self:ShowNotification("Notebook Error", tostring(err), "error")
            end
        end
    end, 75)

    CreateButton("Save", function()
        getgenv()._GokuDexNotes = NoteBox.Text
        if writefile then
            pcall(writefile, NotesPath, NoteBox.Text)
            self:ShowNotification("Notebook", "Notes saved to " .. NotesPath, "info")
        else
            self:ShowNotification("Notebook", "Notes saved to memory", "info")
        end
    end, 55)

    CreateButton("Copy", function()
        pcall(setclipboard, NoteBox.Text)
        self:ShowNotification("Notebook", "Copied to clipboard!", "info")
    end, 55)

    CreateButton("Clear", function()
        NoteBox.Text = ""
        UpdateStats()
    end, 55)
end

function Explorer:ToggleNotebook()
    if not self.NotebookWindow or not self.NotebookWindow.Parent then
        self:OpenNotebook()
    else
        self.NotebookWindow.Visible = not self.NotebookWindow.Visible
    end
end

function Explorer:ApplyLayoutPreset(presetName)
    if not self.ExplorerWindow or not self.PropertiesWindow then return end
    local expFrame = self.ExplorerWindow.Frame
    local propFrame = self.PropertiesWindow.Frame
    if not expFrame or not propFrame then return end

    if presetName == "Dual Docked" then
        expFrame.Visible = true
        propFrame.Visible = true
        expFrame.Position = UDim2.new(0, 10, 0, 38)
        expFrame.Size = UDim2.new(0, 360, 1, -48)
        propFrame.Position = UDim2.new(1, -370, 0, 38)
        propFrame.Size = UDim2.new(0, 360, 1, -48)
        self:ShowNotification("GokuDex Layout", "Applied Dual Docked Layout", "info")
    elseif presetName == "Explorer Only" then
        expFrame.Visible = true
        propFrame.Visible = false
        expFrame.Position = UDim2.new(1, -380, 0, 38)
        expFrame.Size = UDim2.new(0, 370, 1, -48)
        self:ShowNotification("GokuDex Layout", "Applied Explorer Only Layout", "info")
    elseif presetName == "Properties Only" then
        expFrame.Visible = false
        propFrame.Visible = true
        propFrame.Position = UDim2.new(1, -380, 0, 38)
        propFrame.Size = UDim2.new(0, 370, 1, -48)
        self:ShowNotification("GokuDex Layout", "Applied Properties Only Layout", "info")
    elseif presetName == "Floating" then
        expFrame.Visible = true
        propFrame.Visible = true
        expFrame.Position = UDim2.new(0.5, -390, 0.5, -240)
        expFrame.Size = UDim2.fromOffset(380, 480)
        propFrame.Position = UDim2.new(0.5, 10, 0.5, -240)
        propFrame.Size = UDim2.fromOffset(380, 480)
        self:ShowNotification("GokuDex Layout", "Applied Floating Windows Layout", "info")
    end
end

function Explorer:LoadPlugins()
    if not (listfiles and readfile and isfile) then return end
    local pluginDirs = {"gokudex/plugins", "dex/plugins"}
    if makefolder and isfolder then
        for _, dir in ipairs(pluginDirs) do
            if not isfolder(dir) then pcall(makefolder, dir) end
        end
    end

    local loaded = 0
    for _, dir in ipairs(pluginDirs) do
        local ok, files = pcall(listfiles, dir)
        if ok and type(files) == "table" then
            for _, filePath in ipairs(files) do
                if filePath:sub(-4) == ".lua" or filePath:sub(-5) == ".luau" then
                    local readOk, code = pcall(readfile, filePath)
                    if readOk and code and code ~= "" then
                        local fn, compileErr = loadstring(code, filePath)
                        if fn then
                            local runOk, pluginErr = pcall(fn, {
                                Explorer = self,
                                UI = VexUI,
                                Services = Services,
                                Theme = Theme,
                                ScreenGui = self.ScreenGui
                            })
                            if runOk then
                                loaded = loaded + 1
                            else
                                warn("[GokuDex Plugin Error]", filePath, pluginErr)
                            end
                        else
                            warn("[GokuDex Plugin Syntax Error]", filePath, compileErr)
                        end
                    end
                end
            end
        end
    end
    if loaded > 0 then
        self:ShowNotification("GokuDex Plugins", string.format("Loaded %d custom plugin(s)", loaded), "info")
    end
end

