        Position = UDim2.new(0, 0, 0, 34);
        BackgroundTransparency = 1;
        Font = Fonts.SemiBold;
        Text = "Aura-Charged Explorer for Roblox Worlds";
        TextColor3 = Theme.TextDim;
        TextSize = 13;
        ZIndex = 502;
        Parent = Card;
    })

    local Status = VexUI:CreateInstance("TextLabel", {
        Size = UDim2.new(1, 0, 0, 24);
        Position = UDim2.new(0, 0, 0, 75);
        BackgroundTransparency = 1;
        Font = Fonts.Mono;
        Text = "⚡ Super Saiyan Engine Ready";
        TextColor3 = Theme.Green;
        TextSize = 12;
        ZIndex = 502;
        Parent = Card;
    })

    local Author = VexUI:CreateInstance("TextLabel", {
        Size = UDim2.new(1, 0, 0, 18);
        Position = UDim2.new(0, 0, 1, -20);
        BackgroundTransparency = 1;
        Font = Fonts.Regular;
        Text = "Created by gokuthug1 | Merged with Dex++ & VEX";
        TextColor3 = Theme.TextFaded;
        TextSize = 11;
        ZIndex = 502;
        Parent = Card;
    })

    task.delay(1.4, function()
        Services.TweenService:Create(SplashFrame, TweenInfo.new(0.5, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            BackgroundTransparency = 1
        }):Play()
        Services.TweenService:Create(Card, TweenInfo.new(0.5, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            BackgroundTransparency = 1
        }):Play()
        task.delay(0.5, function()
            if SplashFrame and SplashFrame.Parent then
                SplashFrame:Destroy()
            end
        end)
    end)
