            self:ToggleExplorerFreeze()
        end,
        "FreezeIcon",
        10,
        18
    )
    self.FreezeButton = FreezeButton
    self:InitFreezeState()

    local function ReapplyIfFrozen()
        if self.ExplorerFrozen then
